import java.util.*;

public class PollockConjecture {
    public static void main(String[] args) {
        final int MAX = 1000000;

        // Generate tetrahedral numbers
        List<Integer> tetra = new ArrayList<>();
        List<Integer> oddTetra = new ArrayList<>();
        for (int n = 1; ; n++) {
            long t = (long) n * (n + 1) * (n + 2) / 6;
            if (t > MAX) break;
            tetra.add((int) t);
            if (t % 2 == 1) oddTetra.add((int) t);
        }

        int[] dp = new int[MAX + 1];
        int[] dpOdd = new int[MAX + 1];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);
        Arrays.fill(dpOdd, Integer.MAX_VALUE / 2);
        dp[0] = 0;
        dpOdd[0] = 0;

        for (int t : tetra) {
            for (int i = t; i <= MAX; i++) {
                dp[i] = Math.min(dp[i], dp[i - t] + 1);
            }
        }

        for (int t : oddTetra) {
            for (int i = t; i <= MAX; i++) {
                dpOdd[i] = Math.min(dpOdd[i], dpOdd[i - t] + 1);
            }
        }

        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            System.out.println(dp[n] + " " + dpOdd[n]);
        }
        sc.close();
    }
}

