import java.io.*;
import java.util.*;

public class Main {
    static final int MAX = 1_000_000;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        List<Integer> queries = new ArrayList<>();
        int maxQuery = 0;

        while (true) {
            int n = fs.nextInt();
            if (n == Integer.MIN_VALUE) break;
            if (n == 0) break;
            queries.add(n);
            if (n > maxQuery) maxQuery = n;
        }

        if (queries.isEmpty()) return;

        List<Integer> tetra = new ArrayList<>();
        List<Integer> oddTetra = new ArrayList<>();

        for (int k = 1; ; k++) {
            long t = (long) k * (k + 1) * (k + 2) / 6;
            if (t > maxQuery) break;
            int val = (int) t;
            tetra.add(val);
            if ((val & 1) == 1) oddTetra.add(val);
        }

        int[] dpAll = unboundedMinCoins(maxQuery, tetra);
        int[] dpOdd = unboundedMinCoins(maxQuery, oddTetra);

        StringBuilder sb = new StringBuilder();
        for (int n : queries) {
            sb.append(dpAll[n]).append(' ').append(dpOdd[n]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static int[] unboundedMinCoins(int max, List<Integer> coins) {
        int INF = 1 << 28;
        int[] dp = new int[max + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int c : coins) {
            for (int s = c; s <= max; s++) {
                if (dp[s - c] + 1 < dp[s]) {
                    dp[s] = dp[s - c] + 1;
                }
            }
        }
        return dp;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Integer.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

