int main() {
    // generate tetrahedral numbers
    int n = 1, t, cnt = 0, odd_cnt = 0;
    while (1) {
        t = n * (n + 1) * (n + 2) / 6;
        if (t > MAX) break;
        tetra[cnt++] = t;
        if (t % 2 == 1) {
            odd_tetra[odd_cnt++] = t;
        }
        n++;
    }

    // initialize dp arrays
    for (int i = 1; i <= MAX; i++) {
        dp[i] = INF;
        dp_odd[i] = INF;
    }
    dp[0] = 0;
    dp_odd[0] = 0;

    // DP for all tetrahedral numbers
    for (int i = 0; i < cnt; i++) {
        int val = tetra[i];
        for (int j = val; j <= MAX; j++) {
            if (dp[j - val] + 1 < dp[j])
                dp[j] = dp[j - val] + 1;
        }
    }

    // DP for odd tetrahedral numbers
    for (int i = 0; i < odd_cnt; i++) {
        int val = odd_tetra[i];
        for (int j = val; j <= MAX; j++) {
            if (dp_odd[j - val] + 1 < dp_odd[j])
                dp_odd[j] = dp_odd[j - val] + 1;
        }
    }

    int x;
    while (scanf("%d", &x) == 1 && x != 0) {
        printf("%d %d\n", dp[x], dp_odd[x]);
    }

    return 0;
